//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
scwin.vScrenID = "ULDSTF08051.xml";
scwin.fr_SecuGrpId = SECUGRP_ID_EN;
scwin.fr_MktId = $c.lce.fn_getMktId(); // 시장구분코드(유가, 코스닥) 전체), 기준은 로그인 사용자의 부서 소속을 기준으로 한다.

scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vIsurCd = "";
scwin.vLIST_STAT_CD = "Y";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; // jackal_11.05.12 상장종목 여부 체크 추가

scwin.fn_search = function() {
    var url = "/etn/EtnMktAct.do?method=searchDelist";
    if (rdo_1_1.getValue() == "1") {
        url += "&DIV_IDX=" + DIV_IDX_ETN_DELLIST_LIST_ISU + "&TRS_IDX=" + TRS_IDX_SELECT + "&ISU_CD=" + txb_ISU_CD.getValue();
    } else if (rdo_1_2.getValue() == "1") {
        if (cmb_ISUR_CD.getSelectedIndex() == 0) {
            url += "&DIV_IDX=" + DIV_IDX_ETN_DELLIST_LIST_ALL + "&TRS_IDX=" + TRS_IDX_SELECT;
        } else {
            url += "&DIV_IDX=" + DIV_IDX_ETN_DELLIST_LIST_CORP + "&TRS_IDX=" + TRS_IDX_SELECT + "&ISUR_CD=" + cmb_ISUR_CD.BindColVal;
        }
    }
    url += "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    //var url = "/Delisting.do?method=searchDelList" + 
    //		      "&DIV_IDX="+DIV_IDX_DELLIST_LIST + "&TRS_IDX="+TRS_IDX_SELECT + "&ISUR_CD=" + cmb_ISUR_CD.BindColVal ;
    //url += "&SCREN_ID=" + vScrenID;
    //url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 ;
    dts.DataID = encodeURI(url);
    dts.reset();
    $c.cm.ShowWin(grd);
};
scwin.fn_search2 = function() {
    var url = "/etn/EtnMktAct.do?method=searchDelist";
    url += "&DIV_IDX=" + DIV_IDX_ETN_DELLIST_LIST_CORP + "&TRS_IDX=" + TRS_IDX_SELECT + "&ISUR_CD=99999";
    //url += "&DIV_IDX="+DIV_IDX_ETN_DELLIST_LIST_ALL + "&TRS_IDX="+TRS_IDX_NEWSEL ;
    url += "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    //var url = "/Delisting.do?method=searchDelList" + 
    //		      "&DIV_IDX="+DIV_IDX_DELLIST_LIST + "&TRS_IDX="+TRS_IDX_SELECT + "&ISUR_CD=99999"  ;
    //url += "&SCREN_ID=" + vScrenID;
    //url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 ;
    dts2.DataID = encodeURI(url);
    dts2.reset();
    $c.cm.ShowWin(grd2);
};
scwin.fn_search3 = function() {
    var url = "/etn/EtnMktAct.do?method=searchDelist";
    url += "&DIV_IDX=" + DIV_IDX_ETN_DELLIST_LOSSLMT_EARY_REDMPT + "&TRS_IDX=" + TRS_IDX_SELECT + "&ISUR_CD=99999" + "&GUBUN_CD=" + "720021";
    url += "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts3.DataID = encodeURI(url);
    dts3.reset();
    $c.cm.ShowWin(grd3);
};
scwin.fn_search4 = function() {
