// dialog 호출용 함수
// 예비심사청구제출기관 호출관련
scwin.fn_GetParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = ""; // 코드값을 포함할 컨트롤
    if (img_Etnlist.getSelectedTabIndex() == "1") {
        arrPar[1] = $c.stf.getObjectValue(txb_ISU_NM); // 명칭값을 포함할 컨트롤

    }
    arrPar[2] = scwin.fr_SecuGrpId; // 명칭값을 포함할 컨트롤

    return arrPar.length;
};
scwin.fn_SetParIsur = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        scwin.fn_changeRadioBtn(1);
        if (img_Etnlist.getSelectedTabIndex() == "1") {
            txb_ISU_CD.setValue(arrPar[0].ISU_CD);
            //txb_ISU_NM.value = arrPar[0].ISU_KOR_NM;
            txb_ISU_NM.setValue(arrPar[0].ISU_KOR_ABBRV);
            scwin.fn_search();
        }
        scwin.vIsurCd = arrPar[0].ISUR_CD;
    }

    //jackal_11.05.12
    // 삭제 종목인 경우 모든 버튼 discable
    scwin.vLIST_STAT_CD = arrPar[0].LIST_STAT_CD;
    if (scwin.vLIST_STAT_CD == "D") {
        if (img_Etnlist.getSelectedTabIndex() == "1") {
            img_Regist.setDisabled(true);
            img_Regist.src = "../img/btn_new_d.gif";
        } else {
            img_Regist2.setDisabled(true);
            img_Regist2.src = "../img/btn_new_d.gif";
        }
    } else {
        if (img_Etnlist.getSelectedTabIndex() == "1") {
            img_Regist.setDisabled(false);
            img_Regist.src = "../img/btn_new.gif";
        } else {
            img_Regist2.setDisabled(false);
            img_Regist2.src = "../img/btn_new.gif";
        }
    }
};
scwin.fn_GetParUpdate = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    if (rdo_1_1.getValue() == "1") {
        arrPar[0] = scwin.vIsurCd; // 발행기관코드값
        arrPar[1] = txb_ISU_NM.getValue(); // 종목명
        arrPar[5] = txb_ISU_CD.getValue(); // 종목코드값
        arrPar[6] = "1"; // 선택 구분(1:종목, 2:발행회사, 3:전체)

    } else if (rdo_1_2.getValue() == "1") {
        if (cmb_ISUR_CD.getSelectedIndex() == 0) {
            arrPar[0] = scwin.vIsurCd; // 발행기관코드값
            arrPar[1] = dts.getCellData(dts.getRowPosition(), "COM_NM"); // 발행기관명
            arrPar[5] = ""; // 종목코드값
            arrPar[6] = "3"; // 선택 구분(1:종목, 2:발행회사, 3:전체)

        } else {
            arrPar[0] = scwin.vIsurCd; // 발행기관코드값
            arrPar[1] = dts.getCellData(dts.getRowPosition(), "COM_NM"); // 발행기관명
            arrPar[5] = ""; // 종목코드값
            arrPar[6] = "2"; // 선택 구분(1:종목, 2:발행회사, 3:전체)

        }
    }
    arrPar[2] = scwin.fr_SecuGrpId; // 증권그룹구분	
    arrPar[3] = scwin.fr_MktId; // 시장구분
    arrPar[4] = dts.getCellData(dts.getRowPosition(), "bz_procs_no"); // 업무처리번호

    return arrPar.length;
};
scwin.fn_GetParNew = function(arrPar) {
    // 신규생성시 지정하는 평션
    if (rdo_1_1.getValue() == "1") {
        arrPar[0] = scwin.vIsurCd; // 발행기관코드값
        arrPar[1] = txb_ISU_NM.getValue(); // 종목명
        arrPar[5] = txb_ISU_CD.getValue(); // 종목코드값
        arrPar[6] = "1"; // 선택 구분(1:종목, 2:발행회사, 3:전체)

    } else if (rdo_1_2.getValue() == "1") {
        if (cmb_ISUR_CD.getSelectedIndex() == 0) {
            arrPar[0] = ""; // 발행기관코드값
            arrPar[1] = ""; // 발행기관명
            arrPar[5] = ""; // 종목코드값
            arrPar[6] = "3"; // 선택 구분(1:종목, 2:발행회사, 3:전체)

        } else {
            arrPar[0] = cmb_ISUR_CD.BindColVal; // 발행기관코드값
            arrPar[1] = cmb_ISUR_CD.getText(); // 발행기관명
            arrPar[5] = ""; // 종목코드값
            arrPar[6] = "2"; // 선택 구분(1:종목, 2:발행회사, 3:전체)

        }
    }
    arrPar[2] = scwin.fr_SecuGrpId; // 증권그룹구분	
    arrPar[3] = scwin.fr_MktId; // 시장구분
    arrPar[4] = ""; // 신규작성시 업무처리번호는 없다.

};
