//etn발행사
scwin.fn_get_isurcode = function() {
    dts_EtnInst.DataID = "/etn/EtnCodeAct.do?method=listIsurCd&For=R";
    dts_EtnInst.Reset();
};
scwin.fn_changeRadioBtn = function(idx) {
    if (idx == "1") {
        cmb_ISUR_CD.setSelectedIndex(0);
        rdo_1_1.setValue("1");
        rdo_1_2.setValue("2");
    } else if (idx == "2") {
        txb_ISU_CD.setValue("");
        txb_ISU_NM.setValue("");
        rdo_1_1.setValue("2");
        rdo_1_2.setValue("1");
    }
};
scwin.img_Etnlist_OnSelChanged = function(nIndex) {
    if (nIndex == 1) {
        rdo_1_1.setValue("1");
        rdo_1_2.setValue("2");
        txb_ISU_CD.setValue("");
        txb_ISU_NM.setValue("");
        cmb_ISUR_CD.setSelectedIndex(0);
        //fn_search();

    } else if (nIndex == 2) // ko_jackal_10.06.15

    {
        scwin.fn_search2();
    } else if (nIndex == 3) {
        scwin.fn_search3();
    } else if (nIndex == 4) {
        scwin.fn_search4();
    }
};
scwin.dts_OnLoadError = function() {
    $c.stf.alert_error(dts);
};
scwin.dts_OnLoadCompleted = function(rowcount) {
    txb_TotCnt.setValue("총 건수 : " + rowcount);
    //dts.RowPosition = rowcount;
    $c.cm.CloseWin(rowcount, grd);
};
